    adcs_quat_t norm_current, norm_target;
    adcs_quat_t conj_current, q_rel;
    double abs_w, clamped_w, angle, req_rate, margin_val;

    if ((current == NULL) || (target == NULL) || (required_rate == NULL) || (margin == NULL)) {
        return ADCS_E_NULL;
    }

    if (adcs_quat_normalize(current, &norm_current) != ADCS_OK) {
        return ADCS_E_RANGE;
    }

    if (adcs_quat_normalize(target, &norm_target) != ADCS_OK) {
        return ADCS_E_RANGE;
    }

    if ((!isfinite(max_rate)) || (max_rate < 0.0)) {
        return ADCS_E_RANGE;
    }

    if ((!isfinite(duration)) || (duration <= 0.0)) {
        return ADCS_E_RANGE;
    }

    conj_current = adcs_quat_conjugate(&norm_current);
    q_rel = adcs_quat_multiply(&norm_target, &conj_current);

    abs_w = fabs(q_rel.w);
    clamped_w = ADCS_CLAMP(abs_w, 0.0, 1.0);
    angle = 2.0 * acos(clamped_w);

    if (!isfinite(angle)) {
        *required_rate = INFINITY;
        *margin = -INFINITY;
        return ADCS_E_RANGE;
    }

    req_rate = angle / duration;

    if (!isfinite(req_rate)) {
        *margin = -INFINITY;
        return ADCS_E_RANGE;
    }

    margin_val = max_rate - req_rate;

    if (!isfinite(margin_val)) {
        return ADCS_E_RANGE;
    }

    *required_rate = req_rate;
    *margin = margin_val;

    return ADCS_OK;
}

